    ('b9f15f49-2851-5efb-b78b-2ef4511ef709'::uuid, 'Quiz — Ce que la Terre reçoit, renvoie et garde', 'Ens. scientifique', '1re', 'Le bilan radiatif de la Terre', '0659ea64-a3e7-545d-a353-ef53d9fa7b1c'::uuid),
    ('10c02699-3d36-5b96-9adf-db4082da8b8b'::uuid, 'Quiz — Comment la lumière devient de la matière', 'Ens. scientifique', '1re', 'La photosynthèse : une conversion de l’énergie solaire', '3b75b1cf-f96a-5d82-86e5-78c1d256ad63'::uuid),
    ('b318afae-fb18-5921-82b4-ccc140ffb414'::uuid, 'Quiz — Tenir 37 °C, quoi qu’il arrive dehors', 'Ens. scientifique', '1re', 'Le bilan thermique du corps humain', '84dd67dc-b676-5af6-9cb4-48cc15bd3113'::uuid),
    ('f50491ce-334e-536f-8d70-17b0bc942627'::uuid, 'Quiz — Mesurer une planète avec une ombre et un angle', 'Ens. scientifique', '1re', 'La forme de la Terre', 'a6a435b7-6d48-5642-a692-8baa878c8c70'::uuid),
    ('7405a916-d163-5871-b3b5-d4ee44422b21'::uuid, 'Quiz — Quatre siècles pour arriver à 4,54 milliards d’années', 'Ens. scientifique', '1re', 'L’histoire de l’âge de la Terre', '45369dfd-5070-5bb1-91a4-4ceba7c6243b'::uuid),
    ('72a30e53-76d1-537e-a8b6-c88bbaaec514'::uuid, 'Quiz — Du géocentrisme aux exoplanètes', 'Ens. scientifique', '1re', 'La Terre dans l’Univers', '6f191bb8-35c4-5b6e-b3a8-6d917c90dfe2'::uuid),
    ('c9582435-5366-5807-bd3e-12a5c944d83b'::uuid, 'Quiz — Une onde qui a besoin de matière', 'Ens. scientifique', '1re', 'Le son, phénomène vibratoire', '59f9144f-d5af-5c35-8479-94ee91d8d1ad'::uuid),
    ('495b9504-d8e1-5135-9764-610b1b96aa00'::uuid, 'Quiz — Des rapports simples aux douze demi-tons', 'Ens. scientifique', '1re', 'La musique ou l’art de faire entendre les nombres', '9816a48e-930b-5566-ba8b-9feee2ad910c'::uuid),
    ('9f872a11-699c-5f77-8804-c53745dea9e3'::uuid, 'Quiz — De l’onde continue à la suite de nombres', 'Ens. scientifique', '1re', 'Le son, une information à coder', '05245a9b-6284-566d-9ffb-206d7de98d7a'::uuid),
    ('65e20049-e508-5bae-8d23-04f41e86e7d7'::uuid, 'Quiz — De la vibration de l’air au message nerveux', 'Ens. scientifique', '1re', 'Entendre la musique', '1c25ec1c-6522-5f39-b75a-dded14000701'::uuid),
    ('ebaec13b-3e98-5d4b-8bf3-f0385f9a2cf3'::uuid, 'Quiz — Proportions, pourcentages et évolutions', 'Ens. scientifique', '1re', 'Analyse de l’information chiffrée', '42c2d1f5-0314-5a57-af68-ad98413584fa'::uuid),
    ('7635fba7-b4ed-5608-b068-3ed9c9a6d3a1'::uuid, 'Quiz — Du hasard aux fréquences stables', 'Ens. scientifique', '1re', 'Phénomènes aléatoires', 'cfa0b055-f4b3-578b-a21c-67adcd0c8d07'::uuid),
    ('f8bea664-cbfe-59b7-8a28-da34269b0e12'::uuid, 'Quiz — Ajouter toujours la même chose', 'Ens. scientifique', '1re', 'Croissance linéaire et suites arithmétiques', '0931eafd-0930-5463-8c11-49c0c07aab50'::uuid),
    ('49a6b4ca-6671-5c56-b436-81b232b49440'::uuid, 'Quiz — La droite, version continue de la suite arithmétique', 'Ens. scientifique', '1re', 'Croissance linéaire et fonctions affines', '684a6451-8368-5f8d-ba12-1ac318d36d8b'::uuid),
    ('9d7f44cd-a199-5547-a5c2-f637a337a375'::uuid, 'Quiz — Multiplier toujours par le même nombre', 'Ens. scientifique', '1re', 'Croissance exponentielle et suites géométriques', '575522c0-2cd9-55fd-b514-1937eca8c56b'::uuid),
    ('ef7b0334-d7f8-5a17-9b15-2e1579a1faf5'::uuid, 'Quiz — La courbe qui s’envole, version continue', 'Ens. scientifique', '1re', 'Croissance et fonctions exponentielles', '7e3275e2-b9a6-55c7-af3a-5d44b0c90157'::uuid),
    ('d3726580-8763-518c-ba5f-ac0f3e880f01'::uuid, 'Quiz — La pente en un point', 'Ens. scientifique', '1re', 'Variation instantanée et nombre dérivé', '981d9ad7-4bfe-5412-b846-919385063c34'::uuid),
    ('d8cd63d5-4a94-53c4-a44e-0b5e15e9ddbe'::uuid, 'Quiz — Du signe de la dérivée au tableau de variation', 'Ens. scientifique', '1re', 'Variation globale et fonction dérivée', '45b5024b-7305-5032-b322-6a45935492ab'::uuid)
  ) AS v(id, title, subject, grade_level, chapter, lesson_id)
