-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('ca484544-1ef6-5d7b-af31-638df640faea'::uuid, 'd2a9207d-32b4-5001-b2dd-c4bf19fbd745'::uuid, 'Qu’est-ce qui définit un élément chimique ?', 'mcq', '["Son nombre de protons (numéro atomique Z)","Son nombre de neutrons","Son nombre total de nucléons","Sa masse volumique"]'::jsonb, 0, 'Deux noyaux de même Z sont le même élément, même si leurs nombres de neutrons diffèrent : ce sont des isotopes.', 1),
    ('14ad6932-f75b-5405-8b2f-424cd042ed8b'::uuid, 'd2a9207d-32b4-5001-b2dd-c4bf19fbd745'::uuid, 'Quels éléments ont été formés dans les premières minutes de l’Univers ?', 'mcq', '["L’hydrogène et l’hélium","Le carbone et l’oxygène","Le fer et le nickel","L’or et l’uranium"]'::jsonb, 0, 'La nucléosynthèse primordiale ne va pas plus loin : tout le reste viendra des étoiles.', 2),
    ('f3c9ff0c-49a6-5bba-adef-4b440fcf768c'::uuid, 'd2a9207d-32b4-5001-b2dd-c4bf19fbd745'::uuid, 'Jusqu’à quel élément la fusion au cœur des étoiles libère-t-elle de l’énergie ?', 'mcq', '["Le fer","Le carbone","L’uranium","L’hélium"]'::jsonb, 0, 'Au-delà du fer, la fusion consommerait de l’énergie : les éléments plus lourds naissent dans les explosions d’étoiles.', 3),
    ('d4740446-83ba-50f5-a85d-0f4f6d389127'::uuid, 'd2a9207d-32b4-5001-b2dd-c4bf19fbd745'::uuid, 'Quel élément représente environ 92 % des atomes de l’Univers ?', 'mcq', '["L’hydrogène","L’hélium","L’oxygène","Le carbone"]'::jsonb, 0, 'L’hélium suit avec près de 8 % ; tout le reste pèse moins de 1 % des atomes.', 4),
    ('65e7abbb-7e3d-5e23-95ac-846e25acd51e'::uuid, 'd2a9207d-32b4-5001-b2dd-c4bf19fbd745'::uuid, 'Quels sont les deux éléments les plus abondants en masse dans la croûte terrestre ?', 'mcq', '["L’oxygène et le silicium","L’hydrogène et l’hélium","Le fer et le nickel","Le carbone et l’azote"]'::jsonb, 0, 'Environ 47 % d’oxygène et 28 % de silicium : la croûte est faite de silicates.', 5),
    ('0b81ab95-ae3f-5aac-b2a9-1f727ad38eb4'::uuid, 'd2a9207d-32b4-5001-b2dd-c4bf19fbd745'::uuid, 'Que reste-t-il d’un échantillon radioactif au bout de deux demi-vies ?', 'mcq', '["Un quart des noyaux initiaux","La moitié","Un huitième","Plus rien"]'::jsonb, 0, 'Une demi-vie divise par deux, deux demi-vies par quatre : la décroissance est multiplicative, jamais linéaire.', 6),
    ('d0336c42-d492-5a0a-b5ba-2646e58fe688'::uuid, 'd2a9207d-32b4-5001-b2dd-c4bf19fbd745'::uuid, 'On peut accélérer la désintégration d’un noyau radioactif en le chauffant fortement.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La demi-vie ne dépend ni de la température, ni de la pression, ni des liaisons chimiques : c’est ce qui en fait une horloge fiable.', 7),
    ('32b510b0-487e-5c7a-a3fb-063432d53f2f'::uuid, 'd2a9207d-32b4-5001-b2dd-c4bf19fbd745'::uuid, 'Quels quatre éléments forment plus de 99 % de la masse du corps humain ?', 'mcq', '["Oxygène, carbone, hydrogène, azote","Fer, calcium, sodium, potassium","Silicium, oxygène, aluminium, fer","Hydrogène, hélium, carbone, azote"]'::jsonb, 0, 'Ce sont les éléments de l’eau et des molécules organiques.', 8),
    ('bc5fa71f-72a9-51fc-9600-3a0492dc3a0d'::uuid, 'e6b9e888-0441-5ce1-a149-6bc4d71a4d9b'::uuid, 'Qu’est-ce qui caractérise un solide cristallin ?', 'mcq', '["Un empilement ordonné et périodique de son motif","Une absence totale d’organisation","Une parfaite transparence","Une origine forcément minérale"]'::jsonb, 0, 'C’est l’ordre à longue distance qui définit le cristal, pas son aspect ni sa provenance.', 1),
    ('6876fbef-a2b8-51c4-a5e8-0bf0e7f9e027'::uuid, 'e6b9e888-0441-5ce1-a149-6bc4d71a4d9b'::uuid, 'Combien d’atomes contient une maille cubique à faces centrées ?', 'mcq', '["4","1","2","8"]'::jsonb, 0, '8 sommets comptés 1/8 et 6 faces comptées 1/2 : 1 + 3 = 4 atomes.', 2),
    ('7b73ecce-4f73-5616-9740-be66dc9e2e47'::uuid, 'e6b9e888-0441-5ce1-a149-6bc4d71a4d9b'::uuid, 'Quelle est la compacité d’une maille cubique simple ?', 'mcq', '["Environ 0,52","Environ 0,74","Environ 0,32","1"]'::jsonb, 0, 'Un peu plus de la moitié du volume est occupée ; la maille cubique à faces centrées atteint 0,74.', 3),
    ('ffeec61d-9471-524f-85b5-b9add006f764'::uuid, 'e6b9e888-0441-5ce1-a149-6bc4d71a4d9b'::uuid, 'Pourquoi le granite présente-t-il de gros cristaux visibles à l’œil nu ?', 'mcq', '["Parce que le magma a refroidi lentement en profondeur","Parce qu’il a refroidi très vite en surface","Parce qu’il est d’origine sédimentaire","Parce qu’il ne contient qu’un seul minéral"]'::jsonb, 0, 'Le temps de refroidissement contrôle la taille des cristaux : lent en profondeur, rapide en surface.', 4),
    ('a250bb3d-b598-5a48-91b0-e36441859021'::uuid, 'e6b9e888-0441-5ce1-a149-6bc4d71a4d9b'::uuid, 'Le verre est un solide cristallin.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est amorphe : ses atomes sont figés en désordre, comme dans un liquide immobilisé.', 5),
    ('1b2f8727-1a87-5947-8a15-d9235ffe07b3'::uuid, 'e6b9e888-0441-5ce1-a149-6bc4d71a4d9b'::uuid, 'Quels minéraux dominent dans le granite ?', 'mcq', '["Quartz, feldspaths et micas","Calcite et gypse","Olivine et pyroxène seuls","Halite et sylvite"]'::jsonb, 0, 'Ces trois familles suffisent à reconnaître un granite à l’œil.', 6),
    ('7b61c738-688a-5aec-96fa-229dde9ea9d3'::uuid, 'e6b9e888-0441-5ce1-a149-6bc4d71a4d9b'::uuid, 'De quoi sont faites les coquilles de mollusques ?', 'mcq', '["De carbonate de calcium","De silice pure","De phosphate de fer","De carbone amorphe"]'::jsonb, 0, 'CaCO3, cristallisé en calcite ou en aragonite sur une trame organique.', 7),
    ('499cecc3-2589-5d7c-aa83-e2b0d4d7dce4'::uuid, 'e6b9e888-0441-5ce1-a149-6bc4d71a4d9b'::uuid, 'Que représente la maille d’un cristal ?', 'mcq', '["Le plus petit volume qui, répété, reconstruit le cristal","La plus grosse pièce visible du minéral","La surface externe du cristal","Le nombre d’électrons de l’atome"]'::jsonb, 0, 'Tout le cristal se déduit de la maille par translations successives.', 8),
    ('1a7ec3ea-578f-5370-9751-dc2870da119c'::uuid, '13116c9d-fefb-5256-a14f-fb892cd9e2fc'::uuid, 'Qu’affirme la théorie cellulaire complétée par Virchow en 1855 ?', 'mcq', '["Toute cellule provient d’une cellule préexistante","Les cellules naissent spontanément de la matière inerte","Seuls les animaux sont formés de cellules","Une cellule peut vivre sans membrane"]'::jsonb, 0, 'C’est la fin de la génération spontanée : la continuité du vivant est cellulaire.', 1),
    ('48f6924b-f6fd-5af6-978c-71181b04a825'::uuid, '13116c9d-fefb-5256-a14f-fb892cd9e2fc'::uuid, 'Quelle est la taille typique d’une cellule animale ?', 'mcq', '["10 à 100 µm","1 à 5 nm","1 à 2 mm","0,1 à 1 µm"]'::jsonb, 0, 'Une bactérie est dix à cent fois plus petite, autour de 1 µm.', 2),
    ('4c97565c-cf14-5d9b-a96c-1d335044ae0e'::uuid, '13116c9d-fefb-5256-a14f-fb892cd9e2fc'::uuid, 'De quoi la membrane plasmique est-elle principalement constituée ?', 'mcq', '["D’une bicouche de phospholipides","D’une paroi de cellulose","D’un feuillet d’ADN","D’une couche de cristaux de calcite"]'::jsonb, 0, 'Des protéines s’y insèrent, mais l’ossature est la bicouche lipidique.', 3),
    ('6e2b2258-58d3-5133-98e4-eb0a1c4ca487'::uuid, '13116c9d-fefb-5256-a14f-fb892cd9e2fc'::uuid, 'Que signifie « molécule amphiphile » ?', 'mcq', '["Elle possède une partie hydrophile et une partie hydrophobe","Elle est soluble dans tous les solvants","Elle change de forme avec la température","Elle ne réagit avec rien"]'::jsonb, 0, 'C’est cette double nature qui fait s’organiser spontanément la bicouche dans l’eau.', 4),
    ('6fd14e3b-5c11-5c48-8d3d-7048c1b5b093'::uuid, '13116c9d-fefb-5256-a14f-fb892cd9e2fc'::uuid, 'Quelle est la limite de résolution d’un microscope optique ?', 'mcq', '["Environ 0,2 µm","Environ 7,5 nm","Environ 1 mm","Environ 10 µm"]'::jsonb, 0, 'Il montre donc la cellule et son noyau, mais pas l’épaisseur de la membrane.', 5),
    ('8da58a30-380f-5c28-9190-d44bd301aabc'::uuid, '13116c9d-fefb-5256-a14f-fb892cd9e2fc'::uuid, 'Qu’est-ce que le métabolisme d’une cellule ?', 'mcq', '["L’ensemble de ses réactions chimiques","Sa vitesse de division","Sa taille au repos","Le nombre de ses chromosomes"]'::jsonb, 0, 'Il dépend du patrimoine génétique de la cellule et des conditions du milieu.', 6),
    ('fa9301d5-7252-5c97-84b3-755f15008483'::uuid, '13116c9d-fefb-5256-a14f-fb892cd9e2fc'::uuid, 'Une cellule chlorophyllienne éclairée est autotrophe pour le carbone.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle fabrique sa matière organique à partir du CO2 minéral, grâce à l’énergie lumineuse.', 7),
    ('49647669-edf5-5b95-a393-2fafbb4d69c1'::uuid, '13116c9d-fefb-5256-a14f-fb892cd9e2fc'::uuid, 'Quelle voie métabolique dégrade la matière organique SANS dioxygène ?', 'mcq', '["La fermentation","La respiration","La photosynthèse","La cristallisation"]'::jsonb, 0, 'Elle libère beaucoup moins d’énergie que la respiration, et produit lactate ou éthanol.', 8),
    ('5056b50c-d54c-5abc-9337-f969ee40b2f0'::uuid, '18c5f7cc-2251-5f78-89d5-cd6348cfc5c7'::uuid, 'Quelle réaction produit l’énergie du Soleil ?', 'mcq', '["La fusion de l’hydrogène en hélium","La fission de l’uranium","La combustion du carbone","La désintégration du potassium"]'::jsonb, 0, 'La masse perdue au cours de la fusion est convertie en énergie selon E = mc².', 1),
    ('0ca6060b-86e1-57e5-8ed4-22add2c2c780'::uuid, '18c5f7cc-2251-5f78-89d5-cd6348cfc5c7'::uuid, 'Que donne la loi de Wien ?', 'mcq', '["La longueur d’onde du maximum d’émission selon la température","La puissance totale émise par une étoile","La distance d’une étoile","La masse d’une étoile"]'::jsonb, 0, 'λmax × T = 2,9 × 10^-3 m·K : la couleur d’un corps chaud renseigne sur sa température.', 2),
    ('23d5b283-64b0-5d66-866d-87f68a4d1a4e'::uuid, '18c5f7cc-2251-5f78-89d5-cd6348cfc5c7'::uuid, 'Quelle est la valeur de la constante solaire au-dessus de l’atmosphère ?', 'mcq', '["Environ 1 360 W/m²","Environ 340 W/m²","Environ 240 W/m²","Environ 5 800 W/m²"]'::jsonb, 0, 'C’est la puissance reçue par un mètre carré placé face au Soleil, à 150 millions de kilomètres.', 3),
    ('515d4fc6-a82d-58d2-82cc-9057f230ca2d'::uuid, '18c5f7cc-2251-5f78-89d5-cd6348cfc5c7'::uuid, 'Si on double la température de surface d’une étoile, par combien la puissance émise par mètre carré est-elle multipliée ?', 'mcq', '["16","2","4","8"]'::jsonb, 0, 'La loi de Stefan est en T⁴ : 2⁴ = 16.', 4),
    ('ce461005-0ab2-5763-9159-7db497a7a6fa'::uuid, '18c5f7cc-2251-5f78-89d5-cd6348cfc5c7'::uuid, 'Pourquoi un mètre carré de sol reçoit-il moins d’énergie aux pôles qu’à l’équateur ?', 'mcq', '["Parce que les rayons y arrivent inclinés et s’étalent sur une plus grande surface","Parce que le Soleil y est plus éloigné","Parce que l’atmosphère y est plus épaisse","Parce que le Soleil y rayonne moins"]'::jsonb, 0, 'La puissance reçue varie avec le cosinus de l’angle d’incidence : c’est l’origine des zones climatiques.', 5),
    ('7ae8d0a1-cf5f-5f13-9f36-6e1b0d75bbbc'::uuid, '18c5f7cc-2251-5f78-89d5-cd6348cfc5c7'::uuid, 'Quelle est approximativement la température de surface du Soleil ?', 'mcq', '["5 800 K","15 millions de K","300 K","1 000 K"]'::jsonb, 0, '15 millions de kelvins, c’est le cœur, où a lieu la fusion ; la surface est bien plus froide.', 6),
    ('4d413f55-8635-5e83-a68d-530612c88c33'::uuid, '18c5f7cc-2251-5f78-89d5-cd6348cfc5c7'::uuid, 'Le Soleil perd de la masse en rayonnant.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Environ 4 millions de tonnes par seconde, converties en énergie selon E = mc².', 7),
    ('327bd585-7a67-54da-86ae-fa9d8bd9a3bc'::uuid, '18c5f7cc-2251-5f78-89d5-cd6348cfc5c7'::uuid, 'Comment évolue la constante solaire si l’on s’éloigne deux fois plus du Soleil ?', 'mcq', '["Elle est divisée par 4","Elle est divisée par 2","Elle est divisée par 8","Elle ne change pas"]'::jsonb, 0, 'La puissance reçue par unité de surface décroît comme 1/d².', 8),
    ('9bc978ad-7536-54f3-bb5c-e55e2543bb79'::uuid, 'b9f15f49-2851-5efb-b78b-2ef4511ef709'::uuid, 'Pourquoi la puissance solaire moyenne reçue par la Terre est-elle de 340 W/m² et non de 1 360 ?', 'mcq', '["Parce que l’énergie interceptée par un disque se répartit sur une sphère quatre fois plus grande","Parce que l’atmosphère en absorbe les trois quarts","Parce que le Soleil ne brille que la moitié du temps","Parce que l’albédo vaut 75 %"]'::jsonb, 0, 'π R² d’interception pour 4 π R² de surface : le rapport est exactement 4.', 1),
    ('8a2e9da2-d0d6-5d69-9bb0-be4f09fb7908'::uuid, 'b9f15f49-2851-5efb-b78b-2ef4511ef709'::uuid, 'Qu’est-ce que l’albédo ?', 'mcq', '["La fraction du rayonnement solaire réfléchie sans être absorbée","La chaleur emmagasinée par les océans","La part d’infrarouge émise par le sol","La puissance de la fusion solaire"]'::jsonb, 0, 'Il vaut environ 0,30 pour la Terre entière, 0,9 pour la neige fraîche et 0,1 pour l’océan.', 2),
    ('bd9f499f-ee59-5461-8d5a-29d21f14f867'::uuid, 'b9f15f49-2851-5efb-b78b-2ef4511ef709'::uuid, 'Quelle serait la température moyenne de surface de la Terre sans effet de serre ?', 'mcq', '["Environ −18 °C","Environ 0 °C","Environ +15 °C","Environ −60 °C"]'::jsonb, 0, 'L’effet de serre naturel apporte les 33 °C qui rendent l’eau liquide possible.', 3),
    ('9131ea76-4b54-58a8-9534-4dd98fbe626d'::uuid, 'b9f15f49-2851-5efb-b78b-2ef4511ef709'::uuid, 'Dans quel domaine la Terre émet-elle son rayonnement thermique ?', 'mcq', '["L’infrarouge","Le visible","L’ultraviolet","Les rayons X"]'::jsonb, 0, 'À 288 K, la loi de Wien place le maximum vers 10 µm, donc dans l’infrarouge.', 4),
    ('bf1ab301-4873-5ab0-936c-cafbaf650b61'::uuid, 'b9f15f49-2851-5efb-b78b-2ef4511ef709'::uuid, 'Quelle était la teneur de l’atmosphère en CO2 avant l’ère industrielle ?', 'mcq', '["Environ 280 ppm","Environ 420 ppm","Environ 30 ppm","Environ 1 000 ppm"]'::jsonb, 0, 'Elle dépasse aujourd’hui 420 ppm, soit une hausse de 50 %.', 5),
    ('7e5be90b-3d26-5875-9379-cb6d52e79415'::uuid, 'b9f15f49-2851-5efb-b78b-2ef4511ef709'::uuid, 'La fonte de la banquise amplifie le réchauffement.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La glace claire cède la place à un océan sombre : l’albédo baisse, l’absorption augmente. C’est une rétroaction positive.', 6),
    ('de9e61ba-7c60-5ef6-bfe9-fbf294b78ba4'::uuid, 'b9f15f49-2851-5efb-b78b-2ef4511ef709'::uuid, 'Quelle puissance la Terre absorbe-t-elle réellement, en moyenne, par mètre carré ?', 'mcq', '["Environ 240 W/m²","Environ 340 W/m²","Environ 100 W/m²","Environ 1 360 W/m²"]'::jsonb, 0, '340 reçus moins 100 réfléchis par l’albédo.', 7),
    ('e99f3f8e-2812-5eae-906c-886b1d946bad'::uuid, 'b9f15f49-2851-5efb-b78b-2ef4511ef709'::uuid, 'Que font les gaz à effet de serre au rayonnement infrarouge du sol ?', 'mcq', '["Ils l’absorbent puis le réémettent dans toutes les directions","Ils le réfléchissent intégralement vers l’espace","Ils le transforment en lumière visible","Ils le laissent passer sans interagir"]'::jsonb, 0, 'Une part revient vers le sol : le sol est chauffé deux fois, par le Soleil et par l’atmosphère.', 8),
    ('b4910a40-bf04-583a-ae51-e46c01615712'::uuid, '10c02699-3d36-5b96-9adf-db4082da8b8b'::uuid, 'Quelle est l’équation bilan de la photosynthèse ?', 'mcq', '["6 CO2 + 6 H2O → C6H12O6 + 6 O2","C6H12O6 + 6 O2 → 6 CO2 + 6 H2O","2 H2 + O2 → 2 H2O","CO2 + CaO → CaCO3"]'::jsonb, 0, 'La seconde équation est celle de la respiration, exactement l’inverse.', 1),
    ('ea6b6d6c-7c05-5838-9070-c746db7564d1'::uuid, '10c02699-3d36-5b96-9adf-db4082da8b8b'::uuid, 'Pourquoi les feuilles sont-elles vertes ?', 'mcq', '["Les pigments absorbent le bleu et le rouge, et réfléchissent le vert","La chlorophylle est un pigment vert qui absorbe le vert","Le vert est la couleur dominante de la lumière solaire","Les feuilles émettent leur propre lumière verte"]'::jsonb, 0, 'Le spectre d’absorption montre deux pics, dans le bleu et dans le rouge.', 2),
    ('deb828af-cfcf-555f-a60f-bdeb9675942c'::uuid, '10c02699-3d36-5b96-9adf-db4082da8b8b'::uuid, 'Quel est l’ordre de grandeur du rendement de la photosynthèse ?', 'mcq', '["Moins de 1 % de l’énergie lumineuse reçue","Environ 30 %","Environ 70 %","Environ 10 %"]'::jsonb, 0, 'Rendement minuscule, mais appliqué à une surface planétaire : environ 100 Gt de carbone fixées par an.', 3),
    ('2070c3fb-0107-5122-82b0-69e765f17041'::uuid, '10c02699-3d36-5b96-9adf-db4082da8b8b'::uuid, 'Dans quel organite la photosynthèse a-t-elle lieu ?', 'mcq', '["Le chloroplaste","La mitochondrie","Le noyau","Le ribosome"]'::jsonb, 0, 'La mitochondrie, elle, est le siège de la respiration cellulaire.', 4),
    ('a40b91ba-d5f7-5311-b0f1-7b484e9dd411'::uuid, '10c02699-3d36-5b96-9adf-db4082da8b8b'::uuid, 'D’où vient principalement le charbon ?', 'mcq', '["De forêts enfouies au Carbonifère","Du plancton des océans actuels","De coulées volcaniques refroidies","De cristaux de carbone formés en profondeur"]'::jsonb, 0, 'Environ 350 millions d’années : c’est de l’énergie solaire fossile.', 5),
    ('35ba8425-c9f2-58d6-80aa-c81d65bd4a55'::uuid, '10c02699-3d36-5b96-9adf-db4082da8b8b'::uuid, 'La photosynthèse consomme du dioxygène et rejette du dioxyde de carbone.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est l’inverse : elle consomme du CO2 et libère de l’O2. La respiration fait le contraire.', 6),
    ('544adba7-9f8e-5f84-bb84-95e9fa8cc41b'::uuid, '10c02699-3d36-5b96-9adf-db4082da8b8b'::uuid, 'Que devient l’énergie lumineuse captée par la plante ?', 'mcq', '["Elle est stockée dans les liaisons chimiques de la matière organique","Elle est intégralement transformée en chaleur","Elle est renvoyée sous forme de lumière verte","Elle est stockée dans le dioxygène libéré"]'::jsonb, 0, 'C’est ce stock que la respiration ou la combustion viendra ensuite libérer.', 7),
    ('cc286b4b-c7b4-5df7-b096-0fb8e1f53990'::uuid, '10c02699-3d36-5b96-9adf-db4082da8b8b'::uuid, 'Quel organisme assure environ la moitié de la production primaire mondiale ?', 'mcq', '["Le phytoplancton des océans","Les forêts tropicales seules","Les prairies tempérées","Les cyanobactéries des sols"]'::jsonb, 0, 'Continents et océans contribuent à parts comparables : les océans par le phytoplancton.', 8),
    ('24e122ed-deb9-5d94-ab5d-a8da3e422619'::uuid, 'b318afae-fb18-5921-82b4-ccc140ffb414'::uuid, 'Quelle est la puissance thermique dissipée par un adulte au repos ?', 'mcq', '["Environ 100 W","Environ 10 W","Environ 1 000 W","Environ 5 W"]'::jsonb, 0, 'Soit de l’ordre de 2 000 kcal par jour, près de 8 400 kJ.', 1),
    ('2eba3cd5-cc05-5115-b6cb-9379c7ddc1c0'::uuid, 'b318afae-fb18-5921-82b4-ccc140ffb414'::uuid, 'Quelle voie d’évacuation fonctionne encore quand l’air est plus chaud que la peau ?', 'mcq', '["L’évaporation de la sueur","Le rayonnement","La convection","La conduction"]'::jsonb, 0, 'Les trois autres exigent que le milieu soit plus froid que le corps ; c’est pourquoi la chaleur humide est dangereuse.', 2),
    ('698089bb-5bf3-5f78-88e3-6771128f403b'::uuid, 'b318afae-fb18-5921-82b4-ccc140ffb414'::uuid, 'Combien vaut 1 kcal en kilojoules ?', 'mcq', '["4,18 kJ","1 kJ","10 kJ","0,24 kJ"]'::jsonb, 0, 'Les étiquettes alimentaires affichent souvent les deux unités.', 3),
    ('3a0cd8c8-94a4-54be-bf88-1121bc6c0650'::uuid, 'b318afae-fb18-5921-82b4-ccc140ffb414'::uuid, 'Quelle structure du cerveau régule la température corporelle ?', 'mcq', '["L’hypothalamus","Le cervelet","L’hypophyse","Le bulbe rachidien"]'::jsonb, 0, 'Il compare l’information des thermorécepteurs à une valeur de consigne.', 4),
    ('69abbf39-e17d-5e5b-9ee6-237f7ec8799e'::uuid, 'b318afae-fb18-5921-82b4-ccc140ffb414'::uuid, 'Que provoque la vasoconstriction des vaisseaux de la peau ?', 'mcq', '["Une diminution des pertes de chaleur","Une augmentation de la sudation","Une hausse du métabolisme de base","Une accélération de l’évaporation"]'::jsonb, 0, 'Moins de sang chaud en surface, donc moins de chaleur cédée au milieu : c’est une réponse au froid.', 5),
    ('ea470ef1-3d6a-511c-bf0e-499386f8dd5c'::uuid, 'b318afae-fb18-5921-82b4-ccc140ffb414'::uuid, 'En dessous de quelle température interne parle-t-on d’hypothermie ?', 'mcq', '["35 °C","37 °C","30 °C","36,5 °C"]'::jsonb, 0, 'En dessous apparaissent confusion, ralentissement cardiaque puis arrêt.', 6),
    ('3e76e3a1-a7e3-5391-aa4f-ce35b2382454'::uuid, 'b318afae-fb18-5921-82b4-ccc140ffb414'::uuid, 'Toute l’énergie des aliments qui n’est pas utilisée en travail finit en chaleur.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est la conséquence directe de la conservation de l’énergie appliquée au corps humain.', 7),
    ('f180b81f-99e0-5b90-ad13-943ff4d41c6a'::uuid, 'b318afae-fb18-5921-82b4-ccc140ffb414'::uuid, 'Quelle énergie faut-il pour évaporer un litre de sueur ?', 'mcq', '["Environ 2 400 kJ","Environ 100 kJ","Environ 42 kJ","Environ 10 000 kJ"]'::jsonb, 0, 'C’est cette chaleur prélevée sur le corps qui refroidit la peau.', 8),
    ('79fb54fa-aabb-50dc-a1be-89c60dac1959'::uuid, 'f50491ce-334e-536f-8d70-17b0bc942627'::uuid, 'Comment Ératosthène a-t-il mesuré la circonférence de la Terre ?', 'mcq', '["En comparant l’ombre d’un gnomon à Alexandrie et un puits éclairé à Syène","En faisant le tour de la Méditerranée en bateau","En mesurant la durée d’une éclipse de Lune","En observant la chute des corps"]'::jsonb, 0, 'L’angle de 7,2° vaut 1/50 de tour : la distance entre les deux villes vaut donc 1/50 de la circonférence.', 1),
    ('bbb474c7-9db5-5a62-b84f-e10a0ac19b3a'::uuid, 'f50491ce-334e-536f-8d70-17b0bc942627'::uuid, 'Quelle valeur Ératosthène trouve-t-il pour le tour de la Terre ?', 'mcq', '["Environ 40 000 km","Environ 6 400 km","Environ 150 millions de km","Environ 12 000 km"]'::jsonb, 0, 'La valeur moderne est de 40 075 km à l’équateur : l’écart est de moins de 1 %.', 2),
    ('dea13390-958d-51d1-9592-c24e74543289'::uuid, 'f50491ce-334e-536f-8d70-17b0bc942627'::uuid, 'Que mesure la latitude d’un lieu ?', 'mcq', '["Son angle par rapport à l’équateur, compté sur un méridien","Son angle par rapport au méridien de Greenwich","Sa distance au pôle Nord en kilomètres","Son altitude au-dessus du niveau de la mer"]'::jsonb, 0, 'De −90° au pôle Sud à +90° au pôle Nord.', 3),
    ('fdda66de-777e-5e65-b16d-db2c17a0934c'::uuid, 'f50491ce-334e-536f-8d70-17b0bc942627'::uuid, 'Combien vaut approximativement un degré de latitude en kilomètres ?', 'mcq', '["111 km","60 km","1 852 km","40 km"]'::jsonb, 0, '40 000 km divisés par 360° : une minute d’arc donne le mille marin, 1 852 m.', 4),
    ('51c3bbbe-9664-54c3-9aa3-34b0f5a8795b'::uuid, 'f50491ce-334e-536f-8d70-17b0bc942627'::uuid, 'Quelle est la formule de la longueur d’un arc de méridien ?', 'mcq', '["L = R × α, avec α en radians","L = R × α, avec α en degrés","L = 2 π R × α","L = R / α"]'::jsonb, 0, 'Convertir l’angle en radians est l’erreur de calcul la plus fréquente de ce chapitre.', 5),
    ('673919c1-f0b6-5532-b70e-47096eb21bbc'::uuid, 'f50491ce-334e-536f-8d70-17b0bc942627'::uuid, 'Quelle est la forme réelle de la Terre ?', 'mcq', '["Un ellipsoïde légèrement aplati aux pôles","Une sphère parfaite","Un disque plat","Un ellipsoïde allongé aux pôles"]'::jsonb, 0, '6 378 km de rayon à l’équateur contre 6 357 km aux pôles : la rotation en est la cause.', 6),
    ('93619f90-032d-5689-8daf-77d49f069869'::uuid, 'f50491ce-334e-536f-8d70-17b0bc942627'::uuid, 'Le plus court chemin entre deux points de la surface terrestre est l’arc de grand cercle.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est l’orthodromie ; la loxodromie, à cap constant, est plus simple à suivre mais plus longue.', 7),
    ('776f2536-48be-5eec-8c0e-0654cc17076e'::uuid, 'f50491ce-334e-536f-8d70-17b0bc942627'::uuid, 'Comment le mètre a-t-il été défini en 1791 ?', 'mcq', '["Comme la dix-millionième partie du quart du méridien terrestre","Comme la longueur d’un pendule battant la seconde","Comme un milliardième du rayon terrestre","Comme la distance parcourue par la lumière en une seconde"]'::jsonb, 0, 'D’où le tour de Terre voisin de 40 000 km : ce n’est pas une coïncidence.', 8),
    ('4bd6e81d-4fd9-57c6-a36f-2094b99b7be2'::uuid, '7405a916-d163-5871-b3b5-d4ee44422b21'::uuid, 'Quelle expérience Buffon a-t-il menée pour estimer l’âge de la Terre ?', 'mcq', '["Le refroidissement de boulets de fer de tailles croissantes","La mesure de l’épaisseur des sédiments","Le comptage des générations bibliques","La datation de météorites"]'::jsonb, 0, 'Il extrapole ensuite à la taille de la Terre et publie 75 000 ans.', 1),
    ('85f9ba03-857f-5f1b-a801-daf1774ad436'::uuid, '7405a916-d163-5871-b3b5-d4ee44422b21'::uuid, 'Pourquoi l’estimation de Kelvin (20 à 100 millions d’années) est-elle fausse ?', 'mcq', '["Il ignorait la chaleur produite par la radioactivité et la convection du manteau","Il avait mal mesuré le rayon de la Terre","Il utilisait une mauvaise valeur de la constante solaire","Il confondait Terre et Soleil"]'::jsonb, 0, 'Un calcul rigoureux mais fondé sur une hypothèse manquante : la radioactivité n’était pas encore découverte.', 2),
    ('ebde4cec-3314-5f0b-b589-d72e09998579'::uuid, '7405a916-d163-5871-b3b5-d4ee44422b21'::uuid, 'Quel est l’âge admis de la Terre ?', 'mcq', '["4,54 milliards d’années","4,54 millions d’années","13,8 milliards d’années","540 millions d’années"]'::jsonb, 0, '13,8 milliards d’années est l’âge de l’Univers, pas celui de la Terre.', 3),
    ('ab5bbce6-0ef2-5c95-bf29-b70787806c6e'::uuid, '7405a916-d163-5871-b3b5-d4ee44422b21'::uuid, 'Pourquoi date-t-on des météorites plutôt que des roches terrestres ?', 'mcq', '["Parce que la tectonique recycle la croûte et efface les roches les plus anciennes","Parce que les météorites sont plus faciles à trouver","Parce que les roches terrestres ne contiennent pas d’uranium","Parce que les météorites sont plus âgées que le système solaire"]'::jsonb, 0, 'Les plus vieilles roches terrestres connues plafonnent vers 4 milliards d’années.', 4),
    ('8caea161-ae87-5df8-a776-7e8e8d31f887'::uuid, '7405a916-d163-5871-b3b5-d4ee44422b21'::uuid, 'Quelle est la demi-vie du carbone 14 ?', 'mcq', '["5 730 ans","1,3 milliard d’années","4,5 milliards d’années","700 000 ans"]'::jsonb, 0, 'Trop courte pour la géologie : au-delà de 50 000 ans, il n’en reste plus assez pour mesurer.', 5),
    ('613203cf-92c2-5e4d-bd8e-3cdaf23689f9'::uuid, '7405a916-d163-5871-b3b5-d4ee44422b21'::uuid, 'Sur quoi repose la datation radiochronologique ?', 'mcq', '["Sur la constance de la demi-vie d’un isotope radioactif","Sur la vitesse de sédimentation des roches","Sur la mesure du champ magnétique terrestre","Sur le comptage des couches de glace"]'::jsonb, 0, 'On compare l’isotope père restant à l’isotope fils accumulé depuis la fermeture du système.', 6),
    ('7ff3c803-fff9-531c-ae27-74d95d69710f'::uuid, '7405a916-d163-5871-b3b5-d4ee44422b21'::uuid, 'Quel âge ont les plus vieux cristaux de zircon connus sur Terre ?', 'mcq', '["Environ 4,4 milliards d’années","Environ 4,54 milliards d’années","Environ 2 milliards d’années","Environ 540 millions d’années"]'::jsonb, 0, 'Trouvés en Australie (Jack Hills), ils sont plus vieux que toute roche entière conservée.', 7),
    ('89415ee3-922b-5140-b732-894985daa92f'::uuid, '7405a916-d163-5871-b3b5-d4ee44422b21'::uuid, 'La découverte de la radioactivité a permis de dater la Terre.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Becquerel en 1896, puis la radiochronologie : c’est elle qui a fourni l’horloge que les géologues cherchaient.', 8),
    ('3e02a4e9-c7c3-500f-ac8f-df4612069ae2'::uuid, '72a30e53-76d1-537e-a8b6-c88bbaaec514'::uuid, 'Qui propose le modèle héliocentrique en 1543 ?', 'mcq', '["Copernic","Ptolémée","Galilée","Newton"]'::jsonb, 0, 'Galilée l’appuiera par ses observations, Kepler le corrigera avec les ellipses, Newton l’expliquera.', 1),
    ('679916a8-0007-598b-9696-837794e917b8'::uuid, '72a30e53-76d1-537e-a8b6-c88bbaaec514'::uuid, 'Quelle observation de Galilée contredit directement le géocentrisme ?', 'mcq', '["Les satellites en orbite autour de Jupiter","Les taches solaires","Les cratères de la Lune","La Voie lactée composée d’étoiles"]'::jsonb, 0, 'Si des astres tournent autour de Jupiter, tout ne tourne pas autour de la Terre. Les phases de Vénus jouent le même rôle.', 2),
    ('d10b80f4-db2d-5a33-8cc2-1cf043b6f49b'::uuid, '72a30e53-76d1-537e-a8b6-c88bbaaec514'::uuid, 'Selon Kepler, quelle est la forme des orbites planétaires ?', 'mcq', '["Des ellipses dont le Soleil occupe un foyer","Des cercles parfaits centrés sur le Soleil","Des spirales","Des cercles centrés sur la Terre"]'::jsonb, 0, 'C’est l’abandon du cercle, dogme antique, qui permet enfin de coller aux observations de Tycho Brahe.', 3),
    ('bae1eb91-a9f8-5311-a31c-3fde3f1a3b53'::uuid, '72a30e53-76d1-537e-a8b6-c88bbaaec514'::uuid, 'Combien de temps la lumière du Soleil met-elle pour atteindre la Terre ?', 'mcq', '["Environ 8 minutes","Environ 1 seconde","Environ 1 heure","Environ 1 an"]'::jsonb, 0, '150 millions de kilomètres à 300 000 km/s.', 4),
    ('470a3097-ad05-5ee0-a757-4a01ab8e343f'::uuid, '72a30e53-76d1-537e-a8b6-c88bbaaec514'::uuid, 'Qu’est-ce que la zone d’habitabilité d’une étoile ?', 'mcq', '["La région où l’eau peut exister à l’état liquide à la surface d’une planète","La zone où la gravité est la plus forte","La région où les planètes sont telluriques","La zone où l’étoile émet le plus d’ultraviolets"]'::jsonb, 0, 'C’est une condition nécessaire mais pas suffisante : encore faut-il une masse et une atmosphère adéquates.', 5),
    ('529d168e-2eae-5b2a-afba-7eccd11f224a'::uuid, '72a30e53-76d1-537e-a8b6-c88bbaaec514'::uuid, 'Sur quoi repose la méthode des transits pour détecter une exoplanète ?', 'mcq', '["Sur la baisse périodique de luminosité de l’étoile","Sur la photographie directe de la planète","Sur le décalage de couleur de la planète","Sur la mesure de son champ magnétique"]'::jsonb, 0, 'La planète passe devant son étoile et en masque une infime fraction, régulièrement.', 6),
    ('ac80b312-02af-5c31-9310-4914e017ad77'::uuid, '72a30e53-76d1-537e-a8b6-c88bbaaec514'::uuid, 'La Terre est une planète tellurique.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Rocheuse, dense et petite, comme Mercure, Vénus et Mars, par opposition aux planètes géantes.', 7),
    ('9bb4bdea-bd8f-56bd-b461-2d5060d28019'::uuid, '72a30e53-76d1-537e-a8b6-c88bbaaec514'::uuid, 'Quelle loi Newton énonce-t-il en 1687 pour expliquer le mouvement des astres ?', 'mcq', '["La gravitation universelle","La loi de Wien","La loi de Stefan","La conservation de la masse"]'::jsonb, 0, 'F = G × m × M / d² : la même force fait tomber une pomme et tourner la Lune.', 8),
    ('3c79bfa7-6328-50f7-afec-9c42a102727f'::uuid, 'c9582435-5366-5807-bd3e-12a5c944d83b'::uuid, 'Pourquoi le son ne se propage-t-il pas dans le vide ?', 'mcq', '["C’est une onde mécanique : il lui faut un milieu matériel","Parce que la lumière y va trop vite","Parce que la température y est trop basse","Parce qu’il n’y a pas de gravité"]'::jsonb, 0, 'Contrairement à la lumière, onde électromagnétique, qui traverse le vide.', 1),
    ('37e16246-dfe4-5d44-ab26-292d11fc332c'::uuid, 'c9582435-5366-5807-bd3e-12a5c944d83b'::uuid, 'Quelle est la célérité du son dans l’air à 20 °C ?', 'mcq', '["Environ 340 m/s","Environ 1 500 m/s","Environ 3 × 10^8 m/s","Environ 5 000 m/s"]'::jsonb, 0, '1 500 m/s est la valeur dans l’eau, 5 000 m/s dans l’acier.', 2),
    ('f3f446f4-fac7-5bb7-8543-71c061825eff'::uuid, 'c9582435-5366-5807-bd3e-12a5c944d83b'::uuid, 'Quelle relation lie longueur d’onde, célérité et fréquence ?', 'mcq', '["λ = v / f","λ = v × f","λ = f / v","λ = v × f²"]'::jsonb, 0, 'La longueur d’onde est la distance parcourue par l’onde pendant une période.', 3),
    ('dd76ea9a-7a21-5921-8c7d-2834881276e2'::uuid, 'c9582435-5366-5807-bd3e-12a5c944d83b'::uuid, 'Quel est le domaine des fréquences audibles par l’oreille humaine ?', 'mcq', '["20 Hz à 20 000 Hz","2 Hz à 2 000 Hz","200 Hz à 200 000 Hz","20 Hz à 2 000 Hz"]'::jsonb, 0, 'En dessous, les infrasons ; au-dessus, les ultrasons.', 4),
    ('2889ed48-6b2b-53b1-9828-849bf0593873'::uuid, 'c9582435-5366-5807-bd3e-12a5c944d83b'::uuid, 'Qu’est-ce qui distingue le timbre d’une flûte de celui d’un violon jouant la même note ?', 'mcq', '["La composition en harmoniques","La fréquence fondamentale","La célérité du son émis","Le niveau sonore en décibels"]'::jsonb, 0, 'La hauteur est la même, ce sont les fréquences multiples du fondamental qui diffèrent.', 5),
    ('8fd7f953-76db-5241-a50c-69c0658426b5'::uuid, 'c9582435-5366-5807-bd3e-12a5c944d83b'::uuid, 'De combien augmente le niveau sonore si l’intensité est multipliée par 10 ?', 'mcq', '["De 10 dB","De 3 dB","De 100 dB","Il est multiplié par 10"]'::jsonb, 0, 'L’échelle est logarithmique : L = 10 log(I/I0).', 6),
    ('5a772c43-3a75-5e29-8fc6-aa56fca06ac5'::uuid, 'c9582435-5366-5807-bd3e-12a5c944d83b'::uuid, 'Deux sources identiques de 80 dB placées côte à côte produisent 160 dB.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Doubler l’intensité n’ajoute que 3 dB : on obtient 83 dB.', 7),
    ('2affe5f7-1708-55f4-89d7-e3999375015c'::uuid, 'c9582435-5366-5807-bd3e-12a5c944d83b'::uuid, 'À partir de quel niveau sonore une exposition prolongée devient-elle risquée ?', 'mcq', '["85 dB","120 dB","60 dB","40 dB"]'::jsonb, 0, '120 dB est le seuil de douleur ; le risque, lui, commence bien avant et dépend aussi de la durée.', 8),
    ('ce434a5f-e0eb-556e-acf3-29d0255b7e91'::uuid, '495b9504-d8e1-5135-9764-610b1b96aa00'::uuid, 'Quel est le rapport de fréquences d’une octave ?', 'mcq', '["2","3/2","4/3","1,059"]'::jsonb, 0, 'Le la3 à 440 Hz donne un la4 à 880 Hz.', 1),
    ('ecd08240-0a72-55ba-baba-499b8fda03e0'::uuid, '495b9504-d8e1-5135-9764-610b1b96aa00'::uuid, 'Quel rapport de fréquences correspond à une quinte ?', 'mcq', '["3/2","2","4/3","5/4"]'::jsonb, 0, 'C’est l’intervalle qui sert à construire la gamme de Pythagore, de quinte en quinte.', 2),
    ('cc85b1fa-c2ae-5a94-8b09-6da3c3c631ad'::uuid, '495b9504-d8e1-5135-9764-610b1b96aa00'::uuid, 'Comment varie la fréquence émise par une corde quand on divise par deux sa longueur vibrante ?', 'mcq', '["Elle est multipliée par deux","Elle est divisée par deux","Elle ne change pas","Elle est multipliée par quatre"]'::jsonb, 0, 'La fréquence est inversement proportionnelle à la longueur : c’est l’expérience du monocorde.', 3),
    ('8a7f39d0-c696-5988-acfa-f95442e0759c'::uuid, '495b9504-d8e1-5135-9764-610b1b96aa00'::uuid, 'Qu’est-ce que le comma pythagoricien ?', 'mcq', '["L’écart entre douze quintes et sept octaves","La plus petite note audible","Le rapport d’un demi-ton tempéré","L’intervalle entre deux notes voisines de la gamme"]'::jsonb, 0, '(3/2)^12 ≈ 129,7 alors que 2^7 = 128 : la gamme construite par quintes ne se referme pas.', 4),
    ('6065eba8-6055-58cb-828a-2ddb2cc5817a'::uuid, '495b9504-d8e1-5135-9764-610b1b96aa00'::uuid, 'Quel est le rapport de fréquences d’un demi-ton dans la gamme tempérée ?', 'mcq', '["2^(1/12) ≈ 1,059","3/2","1,5","2/12"]'::jsonb, 0, 'Douze demi-tons égaux redonnent exactement l’octave : (2^(1/12))^12 = 2.', 5),
    ('e5a0b6de-81ed-5f2b-9280-81e28115fdae'::uuid, '495b9504-d8e1-5135-9764-610b1b96aa00'::uuid, 'Quelle est la fréquence du la3, note de référence de l’accord des instruments ?', 'mcq', '["440 Hz","220 Hz","880 Hz","400 Hz"]'::jsonb, 0, '220 Hz est le la de l’octave inférieure, 880 Hz celui de l’octave supérieure.', 6),
    ('dd03f02f-ff57-5ed0-a833-98b4de636919'::uuid, '495b9504-d8e1-5135-9764-610b1b96aa00'::uuid, 'Dans la gamme tempérée, la quinte est parfaitement juste.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle vaut 1,498 au lieu de 1,5 : le tempérament sacrifie un peu de pureté pour rendre toutes les tonalités jouables.', 7),
    ('280ea50a-6b80-5dbe-af08-fc869a0e2810'::uuid, '495b9504-d8e1-5135-9764-610b1b96aa00'::uuid, 'Pourquoi la gamme tempérée s’est-elle imposée ?', 'mcq', '["Parce qu’elle permet de jouer dans toutes les tonalités","Parce qu’elle rend tous les intervalles parfaitement justes","Parce qu’elle simplifie la fabrication des cordes","Parce qu’elle supprime les harmoniques"]'::jsonb, 0, 'L’erreur est répartie équitablement au lieu de s’accumuler sur certains intervalles.', 8),
    ('18aa4b89-cf86-5b5b-9449-5c4fea2fbdbb'::uuid, '9f872a11-699c-5f77-8804-c53745dea9e3'::uuid, 'Qu’impose le critère de Shannon-Nyquist ?', 'mcq', '["Échantillonner à au moins deux fois la fréquence maximale du signal","Échantillonner à la fréquence maximale du signal","Quantifier sur au moins 16 bits","Compresser avant de transmettre"]'::jsonb, 0, 'D’où les 44,1 kHz du CD audio pour des sons allant jusqu’à 20 kHz.', 1),
    ('0026976f-c5ce-579b-beea-5485c5912f42'::uuid, '9f872a11-699c-5f77-8804-c53745dea9e3'::uuid, 'Combien de niveaux permet une quantification sur 16 bits ?', 'mcq', '["65 536","256","16","1 024"]'::jsonb, 0, '2^16 = 65 536 : c’est la résolution du CD audio.', 2),
    ('5aae1647-65e9-5fda-93ff-318c602f8149'::uuid, '9f872a11-699c-5f77-8804-c53745dea9e3'::uuid, 'Quelle est la fréquence d’échantillonnage du CD audio ?', 'mcq', '["44,1 kHz","20 kHz","16 kHz","96 kHz"]'::jsonb, 0, 'Un peu plus du double de 20 kHz, la limite de l’audition humaine.', 3),
    ('6c34b139-f0c4-5591-9a3a-bb6d9ab26016'::uuid, '9f872a11-699c-5f77-8804-c53745dea9e3'::uuid, 'Que se passe-t-il si la fréquence d’échantillonnage est trop faible ?', 'mcq', '["Un repliement de spectre fait apparaître des fréquences inexistantes","Le fichier devient plus lourd","Le son devient plus aigu","La quantification devient impossible"]'::jsonb, 0, 'Le signal reconstitué contient des fréquences qui n’étaient pas dans le son d’origine.', 4),
    ('842df2da-85a2-5054-b633-082319791bbd'::uuid, '9f872a11-699c-5f77-8804-c53745dea9e3'::uuid, 'Quelle est la taille d’une seconde de son stéréo au format CD non compressé ?', 'mcq', '["Environ 1,4 Mbit","Environ 1,4 kbit","Environ 176 Mbit","Environ 44 kbit"]'::jsonb, 0, '44 100 × 16 × 2 = 1 411 200 bits, soit environ 176 ko.', 5),
    ('44999b3f-3c73-5e9b-8508-a9a8b4eca33f'::uuid, '9f872a11-699c-5f77-8804-c53745dea9e3'::uuid, 'Que perd-on avec une compression MP3 ?', 'mcq', '["Une partie de l’information sonore, non récupérable","Rien, le fichier est restitué à l’identique","Seulement la voie droite du signal","La fréquence d’échantillonnage"]'::jsonb, 0, 'C’est une compression avec perte, qui supprime ce que l’oreille perçoit mal : le gain est d’un facteur dix environ.', 6),
    ('c068c433-818d-56b0-989b-aa6d20f0a5fd'::uuid, '9f872a11-699c-5f77-8804-c53745dea9e3'::uuid, 'La compression FLAC restitue exactement le fichier d’origine.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est une compression sans perte : gain plus modeste, mais aucune information supprimée.', 7),
    ('1017f14c-fa20-5f46-9725-fe6574723efc'::uuid, '9f872a11-699c-5f77-8804-c53745dea9e3'::uuid, 'Quel est l’avantage majeur d’un signal numérique sur un signal analogique ?', 'mcq', '["Il se copie et se transmet sans dégradation","Il occupe toujours moins de place","Il a une meilleure qualité sonore par nature","Il n’a pas besoin d’être quantifié"]'::jsonb, 0, 'Une suite de 0 et de 1 se régénère exactement et se corrige ; une tension continue se dégrade à chaque copie.', 8),
    ('fad5932d-d90a-55af-bc4c-3d9275b39f84'::uuid, '65e20049-e508-5bae-8d23-04f41e86e7d7'::uuid, 'Quel est le rôle de la chaîne des osselets ?', 'mcq', '["Amplifier et transmettre la vibration du tympan à l’oreille interne","Analyser les fréquences du son","Convertir la vibration en message nerveux","Protéger le conduit auditif"]'::jsonb, 0, 'Marteau, enclume et étrier concentrent la force du tympan sur la fenêtre ovale.', 1),
    ('6b3bb561-c877-53a8-b76f-f9dfb10ab439'::uuid, '65e20049-e508-5bae-8d23-04f41e86e7d7'::uuid, 'Où les fréquences aiguës sont-elles détectées dans la cochlée ?', 'mcq', '["À la base, près de l’entrée","Au sommet, au fond du tube","Sur toute la longueur indifféremment","Dans le nerf auditif"]'::jsonb, 0, 'C’est la tonotopie : les graves sont détectés au sommet, les aigus à la base.', 2),
    ('1e6b08bf-48a5-5f87-8c34-57fa9feef57f'::uuid, '65e20049-e508-5bae-8d23-04f41e86e7d7'::uuid, 'Quelles cellules convertissent la vibration en message nerveux ?', 'mcq', '["Les cellules ciliées de l’organe de Corti","Les cellules du tympan","Les neurones du cortex auditif","Les cellules osseuses de l’étrier"]'::jsonb, 0, 'Elles sont situées dans la cochlée, sur la membrane basilaire.', 3),
    ('f6c063db-f68f-54d3-a73a-4d500428d99e'::uuid, '65e20049-e508-5bae-8d23-04f41e86e7d7'::uuid, 'Comment la hauteur d’un son est-elle codée par l’oreille interne ?', 'mcq', '["Par la position des cellules ciliées stimulées","Par l’amplitude du message nerveux","Par la vitesse du son dans la cochlée","Par le nombre d’osselets mis en mouvement"]'::jsonb, 0, 'Chaque zone de la membrane basilaire résonne pour une fréquence donnée.', 4),
    ('d6c7a51d-e6f2-5385-a52d-1b1e689b1e14'::uuid, '65e20049-e508-5bae-8d23-04f41e86e7d7'::uuid, 'Les cellules ciliées détruites par un traumatisme sonore se régénèrent en quelques semaines.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elles ne se régénèrent pas : la perte auditive est définitive.', 5),
    ('1fd57e24-0467-57b5-842a-79137d9883e3'::uuid, '65e20049-e508-5bae-8d23-04f41e86e7d7'::uuid, 'Quel signe doit alerter après une exposition sonore intense ?', 'mcq', '["Des acouphènes ou une sensation d’oreilles cotonneuses","Un léger mal de tête passager","Une vision troublée","Une perte d’équilibre isolée"]'::jsonb, 0, 'Ce sont les symptômes d’un traumatisme sonore, qui peut laisser des séquelles définitives.', 6),
    ('e0fdce87-6d5a-5ab5-8da5-6ae3010c9629'::uuid, '65e20049-e508-5bae-8d23-04f41e86e7d7'::uuid, 'Vers quelle région du cerveau le nerf auditif conduit-il le message ?', 'mcq', '["Les aires auditives du cortex temporal","Le cervelet","Le cortex visuel occipital","La moelle épinière"]'::jsonb, 0, 'C’est là que le message est identifié et associé à la mémoire et aux émotions.', 7),
    ('6bbe1e20-dafe-5f96-97d0-b2a8275af7b3'::uuid, '65e20049-e508-5bae-8d23-04f41e86e7d7'::uuid, 'Quel est le rôle du tympan ?', 'mcq', '["Vibrer sous l’effet des variations de pression de l’air","Analyser les fréquences du son","Produire le message nerveux","Amplifier le son par résonance de liquide"]'::jsonb, 0, 'Il transmet ensuite sa vibration aux osselets de l’oreille moyenne.', 8),
    ('91945c63-8daa-5aec-a067-d9ebb3067db9'::uuid, 'ebaec13b-3e98-5d4b-8bf3-f0385f9a2cf3'::uuid, 'Une grandeur passe de 200 à 250. Quel est le taux d’évolution ?', 'mcq', '["+25 %","+50 %","+20 %","+2,5 %"]'::jsonb, 0, 't = (250 − 200)/200 = 0,25, soit +25 %.', 1),
    ('800adc63-dff0-50a8-bfc2-153fded61d60'::uuid, 'ebaec13b-3e98-5d4b-8bf3-f0385f9a2cf3'::uuid, 'À quel coefficient multiplicateur correspond une baisse de 20 % ?', 'mcq', '["0,80","1,20","0,20","−0,20"]'::jsonb, 0, 'CM = 1 + t = 1 + (−0,20) = 0,80.', 2),
    ('d0d4cdd8-11ec-5d94-a50c-8d63e9d33824'::uuid, 'ebaec13b-3e98-5d4b-8bf3-f0385f9a2cf3'::uuid, 'Une hausse de 20 % suivie d’une baisse de 20 % ramène-t-elle à la valeur de départ ?', 'mcq', '["Non, il reste une baisse de 4 %","Oui, exactement","Non, il reste une hausse de 4 %","Cela dépend de la valeur de départ"]'::jsonb, 0, '1,20 × 0,80 = 0,96 : le coefficient global est inférieur à 1, quelle que soit la valeur initiale.', 3),
    ('a5d76d77-5065-50fd-9bb3-4d5d373ff20f'::uuid, 'ebaec13b-3e98-5d4b-8bf3-f0385f9a2cf3'::uuid, 'Quelle baisse annule une hausse de 25 % ?', 'mcq', '["Une baisse de 20 %","Une baisse de 25 %","Une baisse de 30 %","Une baisse de 12,5 %"]'::jsonb, 0, 'Le coefficient réciproque est 1/1,25 = 0,80, soit −20 %.', 4),
    ('78e60ef9-3fe1-52d4-bd8c-2157b1c2eaa5'::uuid, 'ebaec13b-3e98-5d4b-8bf3-f0385f9a2cf3'::uuid, 'Le taux de chômage passe de 8 % à 10 %. Que peut-on dire ?', 'mcq', '["Il augmente de 2 points de pourcentage, soit de 25 %","Il augmente de 2 %","Il augmente de 20 points","Il augmente de 2 points, soit de 20 %"]'::jsonb, 0, 'Point de pourcentage et pourcentage d’évolution sont deux lectures différentes du même écart.', 5),
    ('47f421f1-f254-59b3-8bac-87fc4bea4f17'::uuid, 'ebaec13b-3e98-5d4b-8bf3-f0385f9a2cf3'::uuid, '40 % des élèves sont en 1re, et 25 % d’entre eux prennent l’option théâtre. Quelle proportion de l’établissement cela représente-t-il ?', 'mcq', '["10 %","65 %","15 %","25 %"]'::jsonb, 0, 'Les proportions emboîtées se multiplient : 0,40 × 0,25 = 0,10.', 6),
    ('98056749-d643-5c05-90e5-90191a12e83e'::uuid, 'ebaec13b-3e98-5d4b-8bf3-f0385f9a2cf3'::uuid, 'Que signifie un indice de 112 en base 100 ?', 'mcq', '["Une hausse de 12 % depuis l’année de référence","Une hausse de 112 % depuis l’année de référence","Une valeur de 112 unités","Une baisse de 12 %"]'::jsonb, 0, 'L’indice rapporte chaque valeur à celle de l’année de base, ramenée à 100.', 7),
    ('0ab4f557-95bd-54c2-ac7d-2eeda85712d3'::uuid, 'ebaec13b-3e98-5d4b-8bf3-f0385f9a2cf3'::uuid, 'Deux taux d’évolution successifs s’additionnent.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ce sont les coefficients multiplicateurs qui se multiplient : +10 % puis +10 % donnent +21 %, pas +20 %.', 8),
    ('1fc57dce-8135-554f-b506-ec4460cef360'::uuid, '7635fba7-b4ed-5608-b068-3ed9c9a6d3a1'::uuid, 'Entre quelles valeurs une probabilité est-elle comprise ?', 'mcq', '["Entre 0 et 1","Entre −1 et 1","Entre 0 et 100","Entre 1 et 10"]'::jsonb, 0, '0 pour un événement impossible, 1 pour un événement certain.', 1),
    ('f8bca5df-4a5a-5e40-8518-a8b18bb5af00'::uuid, '7635fba7-b4ed-5608-b068-3ed9c9a6d3a1'::uuid, 'Qu’énonce la loi des grands nombres ?', 'mcq', '["La fréquence observée se rapproche de la probabilité quand le nombre d’essais augmente","Un événement rare finit toujours par se produire","La probabilité augmente avec le nombre d’essais","Les grands échantillons donnent tous la même fréquence exacte"]'::jsonb, 0, 'C’est le pont entre le modèle probabiliste et les données observées.', 2),
    ('3705cafc-2835-552f-9894-889ee60cf922'::uuid, '7635fba7-b4ed-5608-b068-3ed9c9a6d3a1'::uuid, 'Après cinq « pile » consécutifs, quelle est la probabilité d’obtenir « face » au lancer suivant ?', 'mcq', '["1/2","Plus de 1/2","Moins de 1/2","1"]'::jsonb, 0, 'Les lancers sont indépendants : le hasard n’a pas de mémoire.', 3),
    ('3c121aad-8b3b-59dd-ad54-e9967e123a3b'::uuid, '7635fba7-b4ed-5608-b068-3ed9c9a6d3a1'::uuid, 'Qu’est-ce que la fluctuation d’échantillonnage ?', 'mcq', '["La variation de la fréquence observée d’un échantillon à l’autre","Une erreur de mesure de l’expérimentateur","Le changement de probabilité au cours du temps","La différence entre deux probabilités théoriques"]'::jsonb, 0, 'Elle est normale, et elle diminue quand la taille de l’échantillon augmente.', 4),
    ('d9e48f41-f1c5-514b-bf09-619bc1b97eb4'::uuid, '7635fba7-b4ed-5608-b068-3ed9c9a6d3a1'::uuid, 'Par combien faut-il multiplier la taille d’un échantillon pour diviser par 10 la fluctuation ?', 'mcq', '["100","10","1 000","2"]'::jsonb, 0, 'La fluctuation évolue en 1/√n : diviser par 10 exige de multiplier n par 100.', 5),
    ('83fdaadc-de77-53f0-8b42-3ed2ab7759eb'::uuid, '7635fba7-b4ed-5608-b068-3ed9c9a6d3a1'::uuid, 'Quelle est la probabilité d’obtenir un nombre pair avec un dé équilibré à six faces ?', 'mcq', '["0,5","1/6","1/3","2/3"]'::jsonb, 0, 'Trois issues favorables sur six possibles, en situation d’équiprobabilité.', 6),
    ('74f0ba48-e6ac-5cef-bb9a-0fbeefdf1c3d'::uuid, '7635fba7-b4ed-5608-b068-3ed9c9a6d3a1'::uuid, 'La fréquence se mesure sur des données observées, la probabilité est un modèle théorique.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La loi des grands nombres rapproche l’une de l’autre quand le nombre d’essais grandit.', 7),
    ('c51f7524-53a8-5dd3-bf7f-f5b6420eaa7f'::uuid, '7635fba7-b4ed-5608-b068-3ed9c9a6d3a1'::uuid, 'Quel intervalle de fluctuation au seuil de 95 % le programme retient-il pour une proportion p ?', 'mcq', '["[p − 1/√n ; p + 1/√n]","[p − 1/n ; p + 1/n]","[p − √n ; p + √n]","[p − n ; p + n]"]'::jsonb, 0, 'Environ 95 % des échantillons de taille n donnent une fréquence dans cet intervalle.', 8),
    ('39656583-12d9-5b90-8a4a-b57b6e04b44d'::uuid, 'f8bea664-cbfe-59b7-8a28-da34269b0e12'::uuid, 'Comment définit-on une suite arithmétique de raison r ?', 'mcq', '["u(n+1) = u(n) + r","u(n+1) = u(n) × r","u(n+1) = r × n","u(n+1) = u(n)^r"]'::jsonb, 0, 'On ajoute toujours la même quantité : c’est la croissance linéaire.', 1),
    ('40ab4612-9c46-5293-96e2-53af101f54da'::uuid, 'f8bea664-cbfe-59b7-8a28-da34269b0e12'::uuid, 'Quelle est la forme explicite d’une suite arithmétique de premier terme u(0) ?', 'mcq', '["u(n) = u(0) + n × r","u(n) = u(0) × r^n","u(n) = u(0) + r^n","u(n) = n × r"]'::jsonb, 0, 'Elle permet de calculer directement un terme de rang élevé.', 2),
    ('6943c478-ba2c-5bfd-9397-995a6af355ac'::uuid, 'f8bea664-cbfe-59b7-8a28-da34269b0e12'::uuid, 'La suite 3 ; 7 ; 11 ; 15 est-elle arithmétique ?', 'mcq', '["Oui, de raison 4","Non","Oui, de raison 3","Oui, de raison 7"]'::jsonb, 0, 'Les différences entre termes consécutifs sont constantes et valent 4.', 3),
    ('1b49aa96-86c1-53f6-82f7-79073bf7d6a7'::uuid, 'f8bea664-cbfe-59b7-8a28-da34269b0e12'::uuid, 'Un abonnement coûte 40 € d’inscription puis 15 € par mois. Combien a-t-on payé après 24 mois ?', 'mcq', '["400 €","360 €","415 €","600 €"]'::jsonb, 0, 'u(24) = 40 + 15 × 24 = 40 + 360 = 400 €.', 4),
    ('5517dc57-f64b-53cd-a872-0e5e89d15c1d'::uuid, 'f8bea664-cbfe-59b7-8a28-da34269b0e12'::uuid, 'Comment reconnaît-on graphiquement une suite arithmétique ?', 'mcq', '["Ses points sont alignés","Ses points forment une courbe qui s’envole","Ses points forment une hyperbole","Ses points sont dispersés au hasard"]'::jsonb, 0, 'C’est la signature de la croissance linéaire, à ne pas confondre avec la courbe exponentielle.', 5),
    ('2daf02ad-2b6c-5f68-a993-9e59b7bb07ff'::uuid, 'f8bea664-cbfe-59b7-8a28-da34269b0e12'::uuid, 'Combien vaut la somme 1 + 2 + … + 100 ?', 'mcq', '["5 050","10 100","5 000","4 950"]'::jsonb, 0, 'n(n+1)/2 = 100 × 101 / 2 = 5 050.', 6),
    ('481488e9-00f9-5ae5-8bc7-12a6f2a5565d'::uuid, 'f8bea664-cbfe-59b7-8a28-da34269b0e12'::uuid, 'La suite 3 ; 6 ; 12 ; 24 est arithmétique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ses différences (3, 6, 12) ne sont pas constantes : elle est géométrique, de raison 2.', 7),
    ('f1bf2112-435d-5ff5-afd5-2ae9f5fe451e'::uuid, 'f8bea664-cbfe-59b7-8a28-da34269b0e12'::uuid, 'Une suite arithmétique de raison négative est :', 'mcq', '["Décroissante","Croissante","Constante","Alternée"]'::jsonb, 0, 'On retranche la même quantité à chaque étape.', 8),
    ('9e909bea-340f-5bb5-be4b-a3de3cf83b17'::uuid, '49a6b4ca-6671-5c56-b436-81b232b49440'::uuid, 'Quelle est la forme générale d’une fonction affine ?', 'mcq', '["f(x) = a x + b","f(x) = a x²","f(x) = a / x","f(x) = a^x"]'::jsonb, 0, 'a est le coefficient directeur, b l’ordonnée à l’origine.', 1),
    ('1d1d301a-b667-55a5-945c-c77ef5007260'::uuid, '49a6b4ca-6671-5c56-b436-81b232b49440'::uuid, 'Que représente le coefficient directeur a ?', 'mcq', '["La variation de f quand x augmente de 1","La valeur de f(0)","Le point d’intersection avec l’axe des abscisses","La pente du repère"]'::jsonb, 0, 'C’est le taux d’accroissement, constant sur toute la droite.', 2),
    ('a7de6d09-e79a-56a5-913b-ef1ff898204f'::uuid, '49a6b4ca-6671-5c56-b436-81b232b49440'::uuid, 'Quelle est la représentation graphique d’une fonction affine ?', 'mcq', '["Une droite","Une parabole","Une hyperbole","Une courbe exponentielle"]'::jsonb, 0, 'Croissante si a > 0, décroissante si a < 0.', 3),
    ('eca7a51e-4afb-56be-85a6-b601ca367e6b'::uuid, '49a6b4ca-6671-5c56-b436-81b232b49440'::uuid, 'Une fonction affine avec b = 0 traduit :', 'mcq', '["Une situation de proportionnalité","Une croissance exponentielle","Une évolution constante","Une suite géométrique"]'::jsonb, 0, 'f(x) = a x : la droite passe par l’origine du repère.', 4),
    ('197e952c-66dc-599e-8ab1-e3eed1cfc9ae'::uuid, '49a6b4ca-6671-5c56-b436-81b232b49440'::uuid, 'Un forfait coûte 10 € plus 0,05 € par minute. Au bout de combien de minutes la facture atteint-elle 25 € ?', 'mcq', '["300 minutes","500 minutes","150 minutes","250 minutes"]'::jsonb, 0, '0,05 x + 10 = 25 donne 0,05 x = 15, soit x = 300.', 5),
    ('c9061f3d-cac9-5142-b97c-bfc390d2fa8f'::uuid, '49a6b4ca-6671-5c56-b436-81b232b49440'::uuid, 'Quel lien unit suite arithmétique et fonction affine ?', 'mcq', '["La raison de la suite est le coefficient directeur de la fonction","La raison est l’ordonnée à l’origine","Il n’y a aucun lien","La suite est le carré de la fonction"]'::jsonb, 0, 'La suite est la restriction de la fonction affine aux valeurs entières.', 6),
    ('d7868698-8f38-520e-8c24-31751491f846'::uuid, '49a6b4ca-6671-5c56-b436-81b232b49440'::uuid, 'Le taux d’accroissement d’une fonction affine dépend des deux points choisis.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est constant : c’est précisément ce qui caractérise une droite.', 7),
    ('cd7c6756-f734-5fc8-a0f9-aa6c02ea5678'::uuid, '49a6b4ca-6671-5c56-b436-81b232b49440'::uuid, 'Quelle précaution s’impose avec un modèle affine ?', 'mcq', '["Ne pas l’extrapoler hors de son domaine de validité","Ne jamais l’utiliser sur des données réelles","Toujours l’appliquer à des valeurs entières","Toujours prendre b = 0"]'::jsonb, 0, 'Prolonger une droite au-delà de l’intervalle observé est une faute classique de lecture de données.', 8),
    ('e17ea23d-ac27-5f1c-ac0b-23f15f479dba'::uuid, '9d7f44cd-a199-5547-a5c2-f637a337a375'::uuid, 'Comment définit-on une suite géométrique de raison q ?', 'mcq', '["u(n+1) = q × u(n)","u(n+1) = u(n) + q","u(n+1) = q^n","u(n+1) = u(n) / n"]'::jsonb, 0, 'On multiplie toujours par le même nombre : c’est la croissance exponentielle.', 1),
    ('c97f35a7-8164-5cc3-bdd5-ef5dbe8e9dbb'::uuid, '9d7f44cd-a199-5547-a5c2-f637a337a375'::uuid, 'Quelle est la forme explicite d’une suite géométrique ?', 'mcq', '["u(n) = u(0) × q^n","u(n) = u(0) + n q","u(n) = q × n","u(n) = u(0)^n"]'::jsonb, 0, 'C’est la puissance qui fait toute la différence avec le modèle linéaire.', 2),
    ('036f7514-397a-5444-8bbb-d7713b531e77'::uuid, '9d7f44cd-a199-5547-a5c2-f637a337a375'::uuid, 'Un capital de 1 000 € est placé à 4 % par an. Que vaut-il après 10 ans ?', 'mcq', '["Environ 1 480 €","Exactement 1 400 €","Environ 1 040 €","Environ 2 000 €"]'::jsonb, 0, '1 000 × 1,04^10 : les intérêts produisent eux-mêmes des intérêts.', 3),
    ('0dcbd452-d981-5622-8a94-5209f51b90a5'::uuid, '9d7f44cd-a199-5547-a5c2-f637a337a375'::uuid, 'Quelle raison correspond à une baisse annuelle de 15 % ?', 'mcq', '["0,85","−0,15","1,15","0,15"]'::jsonb, 0, 'q = 1 + t = 1 − 0,15 = 0,85.', 4),
    ('46b7e347-a529-50e4-ba98-51ebd31cb018'::uuid, '9d7f44cd-a199-5547-a5c2-f637a337a375'::uuid, 'Que se passe-t-il si la raison q est comprise entre 0 et 1 ?', 'mcq', '["La suite décroît vers 0 sans jamais l’atteindre","La suite croît de plus en plus vite","La suite est constante","La suite devient négative"]'::jsonb, 0, 'C’est le modèle de la décroissance radioactive ou d’une population qui décline.', 5),
    ('88aa9e39-8978-5b21-bb6f-deda1bbea97c'::uuid, '9d7f44cd-a199-5547-a5c2-f637a337a375'::uuid, 'Comment distingue-t-on une suite arithmétique d’une suite géométrique ?', 'mcq', '["Différences constantes pour l’une, quotients constants pour l’autre","Par le signe du premier terme","Par le nombre de termes","Par la valeur du rang n"]'::jsonb, 0, 'C’est le seul test à faire, et il suffit.', 6),
    ('d459053b-8ece-56f2-9b83-8738435476b8'::uuid, '9d7f44cd-a199-5547-a5c2-f637a337a375'::uuid, 'Une croissance exponentielle finit toujours par dépasser une croissance linéaire.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Quel que soit le coefficient directeur de la droite, la courbe exponentielle finit par la dépasser.', 7),
    ('66e14dcf-91e8-52e6-bf77-a97a9601f608'::uuid, '9d7f44cd-a199-5547-a5c2-f637a337a375'::uuid, 'Quel est l’ordre de grandeur du temps de doublement pour une croissance de 4 % par an ?', 'mcq', '["Environ 17 ans","Environ 4 ans","Environ 25 ans","Environ 50 ans"]'::jsonb, 0, 'La règle approchée 70/t donne 70/4 ≈ 17,5 ans.', 8),
    ('1067a251-34f8-5111-831c-87ac92b2db3b'::uuid, 'ef7b0334-d7f8-5a17-9b15-2e1579a1faf5'::uuid, 'Quelle est la forme d’une fonction exponentielle de base q ?', 'mcq', '["f(x) = k × q^x","f(x) = k × x^q","f(x) = k x + q","f(x) = k / x^q"]'::jsonb, 0, 'La variable est à l’exposant : c’est ce qui distingue exponentielle et fonction puissance.', 1),
    ('69aa4bc2-829b-5901-a3d7-290284d40754'::uuid, 'ef7b0334-d7f8-5a17-9b15-2e1579a1faf5'::uuid, 'Une fonction exponentielle peut-elle prendre des valeurs négatives ?', 'mcq', '["Non, elle est toujours strictement positive","Oui, si q est négatif","Oui, si x est négatif","Oui, si k vaut 0"]'::jsonb, 0, 'Elle ne s’annule jamais et ne change jamais de signe.', 2),
    ('a5e5beb8-4038-5aad-8341-93fb10671c7b'::uuid, 'ef7b0334-d7f8-5a17-9b15-2e1579a1faf5'::uuid, 'Quelle propriété fondamentale caractérise l’exponentielle ?', 'mcq', '["q^(a+b) = q^a × q^b","q^(a+b) = q^a + q^b","q^(a×b) = q^a + q^b","q^a = a^q"]'::jsonb, 0, 'Additionner les durées revient à multiplier les facteurs : c’est la définition même de la croissance exponentielle.', 3),
    ('43e018ce-6e1f-52a6-834c-fc6bf5c24add'::uuid, 'ef7b0334-d7f8-5a17-9b15-2e1579a1faf5'::uuid, 'Que devient une courbe exponentielle tracée avec un axe vertical en échelle logarithmique ?', 'mcq', '["Une droite","Une parabole","Une courbe encore plus raide","Une horizontale"]'::jsonb, 0, 'C’est le repère graphique le plus sûr pour identifier une croissance exponentielle.', 4),
    ('4983b69b-01f6-5382-bed1-91574639cd08'::uuid, 'ef7b0334-d7f8-5a17-9b15-2e1579a1faf5'::uuid, 'Quelle formule décrit la décroissance radioactive ?', 'mcq', '["N(t) = N0 × 0,5^(t/T)","N(t) = N0 − t/T","N(t) = N0 × t^0,5","N(t) = N0 / t"]'::jsonb, 0, 'T est la demi-vie : c’est bien une fonction exponentielle de base 0,5.', 5),
    ('2cc90674-8aa4-5a00-b68f-e3414471590d'::uuid, 'ef7b0334-d7f8-5a17-9b15-2e1579a1faf5'::uuid, 'Le temps de doublement d’une croissance exponentielle change-t-il au cours du temps ?', 'mcq', '["Non, il est constant","Oui, il augmente","Oui, il diminue","Il dépend de la valeur initiale"]'::jsonb, 0, 'C’est même le meilleur critère de reconnaissance d’un modèle exponentiel.', 6),
    ('030977a5-049c-59aa-bab5-34e2b6c46ca5'::uuid, 'ef7b0334-d7f8-5a17-9b15-2e1579a1faf5'::uuid, 'Une fonction exponentielle de base 0,8 est décroissante.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Pour 0 < q < 1, la fonction décroît vers 0 sans jamais l’atteindre.', 7),
    ('5d81dd97-a453-5205-9d0b-07fa3c4dc334'::uuid, 'ef7b0334-d7f8-5a17-9b15-2e1579a1faf5'::uuid, 'Quel lien unit suite géométrique et fonction exponentielle ?', 'mcq', '["La suite est la restriction de la fonction aux valeurs entières","La suite est la dérivée de la fonction","Il n’y a aucun lien","La fonction est la somme des termes de la suite"]'::jsonb, 0, 'Même raison, même croissance : l’une procède par pas, l’autre en continu.', 8),
    ('de1bb52f-0605-5419-a6e3-2b6436dc8dc6'::uuid, 'd3726580-8763-518c-ba5f-ac0f3e880f01'::uuid, 'Que vaut le taux de variation moyen de f entre a et b ?', 'mcq', '["(f(b) − f(a)) / (b − a)","(f(b) + f(a)) / (b + a)","f(b) − f(a)","(b − a) / (f(b) − f(a))"]'::jsonb, 0, 'C’est le coefficient directeur de la sécante qui joint les deux points.', 1),
    ('003f3a0a-4bb2-55b3-9edd-ea97735143e2'::uuid, 'd3726580-8763-518c-ba5f-ac0f3e880f01'::uuid, 'Que représente graphiquement le nombre dérivé f’(a) ?', 'mcq', '["Le coefficient directeur de la tangente à la courbe au point d’abscisse a","L’ordonnée du point d’abscisse a","L’aire sous la courbe jusqu’à a","La longueur de la sécante"]'::jsonb, 0, 'La sécante devient tangente quand le second point se rapproche du premier.', 2),
    ('53b93555-7629-5dc1-8588-df37b3a047ad'::uuid, 'd3726580-8763-518c-ba5f-ac0f3e880f01'::uuid, 'Pour f(x) = x², combien vaut f’(3) ?', 'mcq', '["6","9","3","0"]'::jsonb, 0, '((3+h)² − 9)/h = 6 + h, qui tend vers 6 quand h tend vers 0.', 3),
    ('6e59284c-caee-55a1-9b46-3954c30be02d'::uuid, 'd3726580-8763-518c-ba5f-ac0f3e880f01'::uuid, 'Quelle est l’équation de la tangente à la courbe de f au point d’abscisse a ?', 'mcq', '["y = f’(a)(x − a) + f(a)","y = f(a)(x − a) + f’(a)","y = f’(a) x","y = f(a) x + f’(a)"]'::jsonb, 0, 'Elle passe par le point (a ; f(a)) et a pour pente f’(a).', 4),
    ('6e27918f-10c7-59db-8730-4b037bbb7a9e'::uuid, 'd3726580-8763-518c-ba5f-ac0f3e880f01'::uuid, 'Que peut-on dire si f’(a) = 0 ?', 'mcq', '["La tangente est horizontale en a","La fonction s’annule en a","La fonction n’est pas définie en a","La fonction est croissante en a"]'::jsonb, 0, 'C’est souvent le signe d’un maximum ou d’un minimum local.', 5),
    ('3ef3eaf9-4a34-572a-9970-ba3a8ae33273'::uuid, 'd3726580-8763-518c-ba5f-ac0f3e880f01'::uuid, 'Si x(t) désigne la position d’un mobile, que représente x’(t) ?', 'mcq', '["Sa vitesse instantanée","Sa distance parcourue","Son accélération","Sa vitesse moyenne"]'::jsonb, 0, 'Et la dérivée de la vitesse donne, elle, l’accélération.', 6),
    ('e04cc378-cf31-5617-b7fc-b7ccd8ec0cd3'::uuid, 'd3726580-8763-518c-ba5f-ac0f3e880f01'::uuid, 'Le taux de variation moyen d’une fonction affine dépend des deux points choisis.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est constant et vaut le coefficient directeur : c’est ce qui caractérise une droite.', 7),
    ('dfc03b60-f252-5293-b47a-af29b0d17c53'::uuid, 'd3726580-8763-518c-ba5f-ac0f3e880f01'::uuid, 'Comment obtient-on le nombre dérivé à partir du taux de variation ?', 'mcq', '["En faisant tendre h vers 0 dans (f(a+h) − f(a))/h","En prenant h très grand","En multipliant le taux par h","En prenant la moyenne de tous les taux"]'::jsonb, 0, 'On passe de la variation moyenne à la variation instantanée.', 8),
    ('a8b15160-8bdd-580c-a3fb-5463e9e4de77'::uuid, 'd8cd63d5-4a94-53c4-a44e-0b5e15e9ddbe'::uuid, 'Quelle est la dérivée de f(x) = x² ?', 'mcq', '["f’(x) = 2x","f’(x) = x","f’(x) = x³/3","f’(x) = 2"]'::jsonb, 0, 'Et la dérivée de x³ est 3x².', 1),
    ('4d716b69-7029-50b8-9bb0-bb85d7981bcf'::uuid, 'd8cd63d5-4a94-53c4-a44e-0b5e15e9ddbe'::uuid, 'Quelle est la dérivée de f(x) = 3x² − 5x + 2 ?', 'mcq', '["f’(x) = 6x − 5","f’(x) = 6x − 5 + 2","f’(x) = 3x − 5","f’(x) = 6x"]'::jsonb, 0, 'On dérive terme à terme : (u + v)’ = u’ + v’, et la dérivée d’une constante est nulle.', 2),
    ('5b627bdd-b4a2-536a-ae45-119aed650545'::uuid, 'd8cd63d5-4a94-53c4-a44e-0b5e15e9ddbe'::uuid, 'Que peut-on conclure si f’(x) > 0 sur un intervalle ?', 'mcq', '["f est croissante sur cet intervalle","f est positive sur cet intervalle","f est décroissante","f est constante"]'::jsonb, 0, 'Le signe de la dérivée donne le sens de variation, pas le signe de la fonction.', 3),
    ('4c5b1c93-cc59-53cf-8ea8-9c300b5fb46d'::uuid, 'd8cd63d5-4a94-53c4-a44e-0b5e15e9ddbe'::uuid, 'Quelle est la dérivée d’une fonction constante ?', 'mcq', '["0","1","La constante elle-même","x"]'::jsonb, 0, 'Rien ne varie, donc la variation instantanée est nulle partout.', 4),
    ('24cd4020-3767-5ae6-a676-65287e187dbc'::uuid, 'd8cd63d5-4a94-53c4-a44e-0b5e15e9ddbe'::uuid, 'À quelle condition un point où f’ s’annule est-il un extremum ?', 'mcq', '["Il faut que f’ change de signe en ce point","Il suffit que f’ s’annule","Il faut que f s’annule aussi","Il faut que f soit positive"]'::jsonb, 0, 'f(x) = x³ a une dérivée nulle en 0 sans extremum : la dérivée y garde le même signe.', 5),
    ('92d25933-468d-5e7b-afc1-f3b4cc41d895'::uuid, 'd8cd63d5-4a94-53c4-a44e-0b5e15e9ddbe'::uuid, 'Pour f(x) = −2x² + 8x + 3, en quelle valeur de x la fonction atteint-elle son maximum ?', 'mcq', '["x = 2","x = 4","x = 0","x = 8"]'::jsonb, 0, 'f’(x) = −4x + 8 s’annule en x = 2 en passant du positif au négatif.', 6),
    ('8f67d2db-3a3c-5409-bcdc-3686245025c4'::uuid, 'd8cd63d5-4a94-53c4-a44e-0b5e15e9ddbe'::uuid, 'Étudier les variations d’une fonction revient à étudier le signe de sa dérivée.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est le théorème central du chapitre, et la méthode de tout tableau de variation.', 7),
    ('49bf3502-233f-58ef-aae8-38b664a7b968'::uuid, 'd8cd63d5-4a94-53c4-a44e-0b5e15e9ddbe'::uuid, 'Quelle est la dérivée de f(x) = a x + b ?', 'mcq', '["f’(x) = a","f’(x) = a x","f’(x) = b","f’(x) = a + b"]'::jsonb, 0, 'La pente d’une droite est la même partout : la dérivée est constante.', 8)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('enseignement-scientifique');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('enseignement-scientifique')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 258 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 258 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
